import{_ as a,o as i,c as l,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- RBD: export diff between clone/parent","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- RBD: export diff between clone/parent","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","RBD","Multi","object transaction","OSD transaction","Transaction coordination"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_export_diff_between_clone_parent.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_export_diff_between_clone_parent.md","lastUpdated":1780459816000}'),o={name:"posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_export_diff_between_clone_parent.md"};function n(r,t,s,_,d,c){return i(),l("div",null,[...t[0]||(t[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>本次会议主要讨论了Ceph中RBD（Rados Block Device）的克隆和父卷之间的差异导出功能，以及如何实现多对象事务，并确保事务的原子性、一致性和持久性。</p><h4 id="关键议题" tabindex="-1">关键议题 <a class="header-anchor" href="#关键议题" aria-label="Permalink to &quot;关键议题&quot;">​</a></h4><ol><li><strong>RBD差异导出</strong>：会议讨论了如何实现克隆和父卷之间的差异导出，以便于备份和恢复。</li><li><strong>OSD事务实现</strong>：重点讨论了如何实现多对象事务，并确保事务的原子性、一致性、隔离性和持久性。</li><li><strong>事务协调</strong>：讨论了事务协调器的选择、事务的提交和回滚机制。</li><li><strong>死锁检测与避免</strong>：讨论了如何检测和避免事务中的死锁问题。</li><li><strong>事务日志</strong>：讨论了事务日志的存储位置和格式。</li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><strong>事务模型</strong>：采用两阶段提交模型，将事务发送到主节点，由主节点协调事务的执行。</li><li><strong>事务日志</strong>：将事务日志存储在内部对象空间中，与headset对象类似，以便持久化。</li><li><strong>死锁检测</strong>：通过比较事务涉及的对象集合来检测死锁，并在冲突时回滚事务。</li><li><strong>读事务</strong>：支持读事务，通过在主节点上获取读锁来保证一致性。</li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><strong>实现RBD差异导出</strong>：开发人员将实现RBD克隆和父卷之间的差异导出功能。</li><li><strong>实现多对象事务</strong>：开发人员将实现多对象事务的功能，并进行测试。</li><li><strong>优化事务性能</strong>：评估事务性能，并进行优化。</li><li><strong>文档编写</strong>：撰写相关文档，说明多对象事务的实现和使用方法。</li></ol><h4 id="讨论要点" tabindex="-1">讨论要点 <a class="header-anchor" href="#讨论要点" aria-label="Permalink to &quot;讨论要点&quot;">​</a></h4><ol><li><strong>RBD差异导出</strong>：实现克隆和父卷之间的差异导出，以便于备份和恢复。</li><li><strong>事务协调</strong>：主节点负责协调事务的执行，确保事务的原子性和一致性。</li><li><strong>死锁检测</strong>：通过比较事务涉及的对象集合来检测死锁，并在冲突时回滚事务。</li><li><strong>事务日志</strong>：将事务日志存储在内部对象空间中，以便持久化。</li><li><strong>读事务</strong>：支持读事务，通过在主节点上获取读锁来保证一致性。</li></ol><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ol><li>会议讨论了liberados系统在实现多对象事务时的局限性，以及如何通过优化现有协议来提高性能。</li><li>会议还讨论了多对象事务在liberados系统中的应用场景，例如垃圾收集和元数据更新。</li><li>会议还讨论了不同事务模型和死锁检测方法的优缺点。</li></ol><h4 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h4><ul><li>Ceph</li><li>RBD</li><li>Multi-object transaction</li><li>OSD transaction</li><li>Transaction coordination</li><li>Deadlock detection</li><li>Transaction log</li><li>liberados</li><li>Atomicity</li><li>Consistency</li><li>Isolation</li><li>Durability</li></ul>',15)])])}const f=a(o,[["render",n]]);export{g as __pageData,f as default};
